package com.medibook.service;
import com.medibook.dto.DoctorDtos.*; import com.medibook.dto.AppointmentDtos.Slot; import com.medibook.entity.*; import com.medibook.repository.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.data.jpa.domain.Specification; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.HttpStatus; import jakarta.persistence.criteria.JoinType; import jakarta.persistence.criteria.Predicate; import java.math.BigDecimal; import java.time.*; import java.util.*;
@Service public class DoctorService {
 private final DoctorProfileRepository doctors;private final UserRepository users;private final SpecialtyRepository specialties;private final AvailabilityRepository availability;private final AppointmentRepository appointments;private final ZoneId zone;
 public DoctorService(DoctorProfileRepository d,UserRepository u,SpecialtyRepository s,AvailabilityRepository a,AppointmentRepository p,@Value("${medibook.timezone:Asia/Kolkata}") String zone){doctors=d;users=u;specialties=s;availability=a;appointments=p;this.zone=ZoneId.of(zone);}
 @Transactional(readOnly=true) public List<DoctorView> search(String specialty,String location,BigDecimal maxFee){
  String normalizedSpecialty=blank(specialty),normalizedLocation=blank(location);
  Specification<DoctorProfile> spec=(root,query,cb)->{
   List<Predicate> predicates=new ArrayList<>();
   predicates.add(cb.isTrue(root.get("verified")));
   predicates.add(cb.isTrue(root.join("user",JoinType.INNER).get("active")));
   if(normalizedSpecialty!=null){var specialtyJoin=root.join("specialty",JoinType.LEFT);predicates.add(cb.equal(cb.lower(specialtyJoin.get("name")),normalizedSpecialty.toLowerCase(Locale.ROOT)));}
   if(normalizedLocation!=null)predicates.add(cb.like(cb.lower(root.get("location")),"%"+normalizedLocation.toLowerCase(Locale.ROOT)+"%"));
   if(maxFee!=null)predicates.add(cb.lessThanOrEqualTo(root.get("consultationFee"),maxFee));
   return cb.and(predicates.toArray(Predicate[]::new));
  };
  return doctors.findAll(spec).stream().map(this::view).toList();
 }
 @Transactional(readOnly=true) public DoctorView get(long id){return doctors.findById(id).map(this::view).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Doctor not found"));}
 public List<Slot> slots(long id,LocalDate date){if(date.isBefore(LocalDate.now(zone)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Date must be today or later");List<DoctorAvailability> schedules=availability.findByDoctorIdAndDayOfWeek(id,date.getDayOfWeek());List<Slot> out=new ArrayList<>();for(var a:schedules){LocalTime t=a.getStartTime();while(!t.plusMinutes(a.getSlotMinutes()).isAfter(a.getEndTime())){LocalTime end=t.plusMinutes(a.getSlotMinutes());boolean breakConflict=a.getBreakStart()!=null&&t.isBefore(a.getBreakEnd())&&end.isAfter(a.getBreakStart());Instant start=date.atTime(t).atZone(zone).toInstant(),finish=date.atTime(end).atZone(zone).toInstant();if(!breakConflict&&start.isAfter(Instant.now())&&appointments.findConflicts(id,start,finish).isEmpty())out.add(new Slot(start,finish));t=end;}}return out;}
 @Transactional public DoctorView updateProfile(long id,ProfileUpdate in){DoctorProfile d=doctors.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Doctor profile not found"));Specialty s=specialties.findByNameIgnoreCase(in.specialty()).orElseGet(()->specialties.save(new Specialty(in.specialty().trim())));setProfile(d,in,s);return view(doctors.save(d));}
 @Transactional public List<DoctorAvailability> setAvailability(long id,List<AvailabilityInput> inputs){doctors.lockById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Doctor profile not found"));for(var i:inputs){if(!i.startTime().isBefore(i.endTime()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Availability start must be before end");if((i.breakStart()==null)!=(i.breakEnd()==null)||(i.breakStart()!=null&&(!i.breakStart().isBefore(i.breakEnd())||i.breakStart().isBefore(i.startTime())||i.breakEnd().isAfter(i.endTime()))))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Break must be inside working hours");}for(int i=0;i<inputs.size();i++)for(int j=i+1;j<inputs.size();j++){var a=inputs.get(i);var b=inputs.get(j);if(a.dayOfWeek()==b.dayOfWeek()&&a.startTime().isBefore(b.endTime())&&b.startTime().isBefore(a.endTime()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Working periods cannot overlap");}for(var ap:appointments.findByDoctorIdOrderByStartAtAsc(id)){if(ap.getStatus()!=AppointmentStatus.PENDING&&ap.getStatus()!=AppointmentStatus.CONFIRMED)continue;ZonedDateTime local=ap.getStartAt().atZone(zone);boolean fits=inputs.stream().filter(s->s.dayOfWeek()==local.getDayOfWeek()).anyMatch(s->{LocalTime t=local.toLocalTime();LocalTime end=ap.getEndAt().atZone(zone).toLocalTime();boolean inside=!t.isBefore(s.startTime())&&!end.isAfter(s.endTime());boolean breakConflict=s.breakStart()!=null&&t.isBefore(s.breakEnd())&&end.isAfter(s.breakStart());return inside&&!breakConflict;});if(!fits)throw new ResponseStatusException(HttpStatus.CONFLICT,"Availability cannot be changed around an existing appointment");}availability.deleteByDoctorId(id);return availability.saveAll(inputs.stream().map(i->new DoctorAvailability(id,i.dayOfWeek(),i.startTime(),i.endTime(),i.slotMinutes(),i.breakStart(),i.breakEnd())).toList());}
 public List<DoctorAvailability> availability(long id){if(!doctors.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Doctor not found");return availability.findByDoctorIdOrderByDayOfWeekAscStartTimeAsc(id);}
 private DoctorView view(DoctorProfile d){return new DoctorView(d.getUserId(),d.getUser().getFullName(),d.getSpecialty()==null?"General Practice":d.getSpecialty().getName(),d.getQualifications(),d.getExperienceYears(),d.getConsultationFee(),d.getLocation(),d.getBio(),d.isVerified(),d.isManualConfirmation());}
 private void setProfile(DoctorProfile d,ProfileUpdate i,Specialty s){d.getUser().setFullName(i.fullName().trim());d.setSpecialty(s);d.setQualifications(i.qualifications().trim());d.setExperienceYears(i.experienceYears());d.setConsultationFee(i.fee());d.setLocation(i.location().trim());d.setBio(i.bio());d.setManualConfirmation(i.manualConfirmation());}
 private String blank(String v){return v==null||v.isBlank()?null:v.trim();}
}
